fn exec_last_occurrence_position(cafes: &Vec<i8>, cafe: i8) -> usize {
    // Initialize last position to 0, assuming the value appears (guaranteed by problem).
    // Actually, safer to scan fully to find last index.
    let mut last_pos = 0;
    for (idx, &val) in cafes.iter().enumerate() {
        if val == cafe {
            last_pos = idx;
        }
    }
    last_pos
}

fn solve(cafes: Vec<i8>) -> i8 {
    // Use a set to track which values we've checked.
    use std::collections::HashSet;
    let mut seen = HashSet::new();

    // Initialize min_last_pos and result from the first element.
    let mut min_last_pos = cafes.len(); // start with max
    let mut chosen_value = cafes[0];

    for &val in &cafes {
        // Only check each distinct value once.
        if !seen.contains(&val) {
            seen.insert(val);
            let last_pos = exec_last_occurrence_position(&cafes, val);
            // Track the value with the minimal last occurrence position.
            if last_pos < min_last_pos {
                min_last_pos = last_pos;
                chosen_value = val;
            }
        }
    }

    chosen_value
}